// ============================================================================
// i3c_io_xilinx.sv  -  Thin tri-state IO wrapper for AMD/Xilinx 7-series
//
// Drop-in equivalent of rtl/altera/i3c_io_altera.sv: same port list, same drive
// semantics. Select it in i3c_target_top with +define+I3C_IO_CELL=i3c_io_xilinx.
//   - SDA is bidirectional: drive Low / drive High (push-pull) / release (Hi-Z).
//   - SCL is INPUT ONLY: the Target never drives SCL (S1 / R-DRV-02/03).
//
// Drive model (docs/design_decisions.md ┬º3):
//   sda_oe=1, sda_o=0 -> drive Low   (ACK / open-drain 0)
//   sda_oe=1, sda_o=1 -> drive High  (push-pull 1; only in push-pull phases)
//   sda_oe=0          -> release to Hi-Z (external pull-up / bus high-keeper -> 1)
//
// Why an inferred tri-state rather than an instantiated IOBUF:
//   * The core is built out-of-context (syn/xilinx/build.tcl, -mode
//     out_of_context). OOC synthesis inserts no pad buffers, and an IOBUF
//     hard-instantiated here would bury a pad cell inside the IP, which breaks
//     as soon as the IP is not the physical top (the parent would have to route
//     a pad net through hierarchy). The inferred form stays a plain 3-state
//     driver on the SDA port.
//   * When this module *is* at the device boundary (in-context / top-level
//     synthesis) Vivado maps exactly this construct onto one IOBUF
//     (IBUF + OBUFT, T = ~sda_oe) on the SDA pad and an IBUF on SCL, which is
//     what a hand-instantiated IOBUF would give.
//   * No unisim dependency, so the same file simulates in xsim and Icarus
//     without glbl / unisims_ver.
// To force the primitive (e.g. to attach IOSTANDARD/SLEW/DRIVE in RTL instead
// of XDC), replace the `assign SDA = ...` / `assign sda_i = ...` lines with
//   IOBUF u_sda (.IO(SDA), .I(sda_o), .T(~sda_oe), .O(sda_i));
// the port list and semantics are unchanged.
// ============================================================================
`ifndef I3C_IO_XILINX_SV
`define I3C_IO_XILINX_SV

module i3c_io_xilinx (
  // device-agnostic core side
  input  logic sda_oe,   // 1 = drive, 0 = release
  input  logic sda_o,    // value to drive when sda_oe=1
  output logic sda_i,    // sampled SDA
  output logic scl_i,    // sampled SCL
  // physical pads
  inout  wire  SDA,
  input  wire  SCL
);

  // Bidirectional SDA: drive when enabled, else high-Z (pull-up resolves High).
  assign SDA   = sda_oe ? sda_o : 1'bz;
  assign sda_i = SDA;

  // SCL is input only - the Target has no SCL driver (S1).
  assign scl_i = SCL;

endmodule
`endif

